ALTER TABLE public.flow_points_ledger ADD COLUMN provenance_state text NOT NULL DEFAULT 'PENDING';
COMMENT ON COLUMN public.flow_points_ledger.provenance_state IS 'Independent reward integrity review; PENDING Core Swap rows are quarantined from new funding and payout without rewriting historical economics.';
CREATE TABLE public.proposal_votes (proposal_id text NOT NULL REFERENCES public.proposals(id), user_id uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(proposal_id,user_id));
GRANT ALL ON public.proposal_votes TO service_role;
ALTER TABLE public.proposal_votes ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.vote_proposal_once(p_id text,p_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.proposals%ROWTYPE; added integer; BEGIN SELECT * INTO p FROM public.proposals WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Proposal unavailable'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=p_user) THEN RAISE EXCEPTION 'Account unavailable'; END IF; INSERT INTO public.proposal_votes(proposal_id,user_id) VALUES(p_id,p_user) ON CONFLICT DO NOTHING; GET DIAGNOSTICS added=ROW_COUNT; IF added=1 THEN UPDATE public.proposals SET votes=votes+1 WHERE id=p_id RETURNING * INTO p; END IF; RETURN jsonb_build_object('proposal',to_jsonb(p),'alreadyVoted',added=0); END $$;
REVOKE ALL ON FUNCTION public.vote_proposal_once(text,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.vote_proposal_once(text,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.core_swap_provenance_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.reason IN ('CORE_SWAP','CORE_SWAP_V2') THEN IF TG_OP='INSERT' AND NEW.points>0 THEN IF NEW.chain_id IS DISTINCT FROM 677 OR NEW.provenance_state<>'VERIFIED' OR NEW.verified_usd IS NULL OR NEW.verified_usd<5 OR NEW.points>floor(NEW.verified_usd) OR NEW.source_log_index IS NULL OR NEW.source_log_index<0 OR NOT EXISTS (SELECT 1 FROM public.verified_activities v JOIN public.profiles p ON p.id=NEW.user_id WHERE v.activity_id=NEW.verified_activity_id AND v.source_chain_id=677 AND lower(v.source_tx_hash)=lower(NEW.tx_hash) AND v.source_log_index=NEW.source_log_index AND lower(v.user_wallet)=lower(NEW.wallet_address) AND lower(p.wallet_address)=lower(NEW.wallet_address) AND v.status='CONFIRMED' AND v.kind='SWAP_EXECUTED' AND v.evidence_source IN ('ROUTER_V3_RECEIPT','ROUTER_V4_SWAP_ACTIVITY') AND v.amount_raw::numeric>0) THEN RAISE EXCEPTION 'Independent Mainnet swap provenance required'; END IF; END IF; IF NEW.funding_state='FUNDED' AND OLD.funding_state IS DISTINCT FROM 'FUNDED' AND NEW.provenance_state<>'VERIFIED' THEN RAISE EXCEPTION 'Reward provenance review required before funding'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER core_swap_provenance_guard BEFORE INSERT OR UPDATE ON public.flow_points_ledger FOR EACH ROW EXECUTE FUNCTION public.core_swap_provenance_guard();